/**
 * Ground truth for the Site check, decoded from NASA GIBS raster layers:
 *  - MODIS_Water_Mask (250 m)                       → share of water (sea, lake, ocean)
 *  - ASTER_GDEM_Color_Index (~30 m, colour-coded)   → elevation and slope
 *  - NDH_Landslide_Hazard_Distribution_2000 (1 km)  → landslide hazard
 * Colours are decoded exactly with the official GIBS colormaps
 * (src/data/gibsColormaps.ts, generated by scripts/gen_colormaps.py).
 */
import { DEM_COLORS, LANDSLIDE_COLORS, WATER_COLORS } from '../../data/gibsColormaps';
import { GIBS_WMS } from '../../data/gibs';
import { HttpError, withRetry } from '../../data/queue';
import { pointInPolygon, type Ring } from './siteScore';

export interface Raster {
  data: Uint8ClampedArray | Uint8Array;
  width: number;
  height: number;
}

export interface BBox4 {
  lonMin: number;
  lonMax: number;
  latMin: number;
  latMax: number;
}

export interface TerrainStats {
  /** Share of the area covered by water (0–1); NaN if unknown */
  waterFraction: number;
  /** Mean / 90th-percentile / max land elevation, m */
  elevMean: number;
  elevP90: number;
  elevMax: number;
  /** Share of land pixels with slope ≤ GENTLE_SLOPE % */
  gentleFraction: number;
  /** Median slope of land pixels, % */
  slopeMedian: number;
  /** Share of pixels with High / Very High landslide hazard */
  landslideHigh: number;
  /** Pixel size used for slopes, m */
  resolutionM: number;
  /** Which layers could be read */
  available: { water: boolean; dem: boolean; landslide: boolean };
  /** True when the water share was inferred from missing elevation (sea) because the water mask failed */
  waterEstimated: boolean;
}

/** Slope (%) at or below which land is considered easy to build on. */
export const GENTLE_SLOPE = 15;
/** Target pixel size for elevation/slope (m) — larger than the colour bins' step effect. */
export const TARGET_PIXEL_M = 250;
const M_PER_DEG = 111320;

const demMap = new Map(DEM_COLORS);
const slideMap = new Map(LANDSLIDE_COLORS.map(([k, i]) => [k, i]));
const waterSet = new Set(WATER_COLORS);
const HIGH_CLASS = LANDSLIDE_COLORS.findIndex(([, , l]) => /^High$/i.test(l));

const rgbAt = (r: Raster, i: number) => (r.data[i * 4 + 3] === 0 ? -1 : (r.data[i * 4] << 16) | (r.data[i * 4 + 1] << 8) | r.data[i * 4 + 2]);

/** Image size (px) so that pixels are ~TARGET_PIXEL_M, clamped to 16–512. */
export function rasterSize(b: BBox4): { width: number; height: number; pixelM: number } {
  const lat0 = ((b.latMin + b.latMax) / 2) * (Math.PI / 180);
  const wM = (b.lonMax - b.lonMin) * M_PER_DEG * Math.cos(lat0);
  const hM = (b.latMax - b.latMin) * M_PER_DEG;
  const scale = Math.max(1, Math.max(wM, hM) / TARGET_PIXEL_M / 512);
  const width = Math.max(16, Math.min(512, Math.round(wM / TARGET_PIXEL_M / scale)));
  const height = Math.max(16, Math.min(512, Math.round(hM / TARGET_PIXEL_M / scale)));
  return { width, height, pixelM: hM / height };
}

export function wmsUrl(layer: string, b: BBox4, width: number, height: number): string {
  const q = new URLSearchParams({
    SERVICE: 'WMS',
    REQUEST: 'GetMap',
    VERSION: '1.3.0',
    LAYERS: layer,
    STYLES: '',
    CRS: 'EPSG:4326',
    BBOX: [b.latMin, b.lonMin, b.latMax, b.lonMax].join(','),
    WIDTH: String(width),
    HEIGHT: String(height),
    FORMAT: 'image/png',
    TRANSPARENT: 'TRUE',
  });
  return `${GIBS_WMS}?${q}`;
}

/** Pixel-centre mask of the polygon for a raster covering bbox. */
function insideMask(ring: Ring, b: BBox4, w: number, h: number): Uint8Array {
  const m = new Uint8Array(w * h);
  for (let j = 0; j < h; j++) {
    const lat = b.latMax - ((j + 0.5) / h) * (b.latMax - b.latMin);
    for (let i = 0; i < w; i++) {
      const lon = b.lonMin + ((i + 0.5) / w) * (b.lonMax - b.lonMin);
      m[j * w + i] = pointInPolygon([lon, lat], ring) ? 1 : 0;
    }
  }
  return m;
}

const quantile = (sorted: number[], q: number) => (sorted.length ? sorted[Math.min(sorted.length - 1, Math.floor(q * (sorted.length - 1)))] : NaN);

/** Pure analysis of decoded rasters (all three must cover the same bbox). */
export function analyzeTerrain(ring: Ring, b: BBox4, layers: { water?: Raster | null; dem?: Raster | null; landslide?: Raster | null }): TerrainStats {
  const out: TerrainStats = {
    waterFraction: NaN,
    elevMean: NaN,
    elevP90: NaN,
    elevMax: NaN,
    gentleFraction: NaN,
    slopeMedian: NaN,
    landslideHigh: NaN,
    resolutionM: NaN,
    available: { water: !!layers.water, dem: !!layers.dem, landslide: !!layers.landslide },
    waterEstimated: false,
  };
  let waterPx: Uint8Array | null = null;

  if (layers.water) {
    const r = layers.water;
    const mask = insideMask(ring, b, r.width, r.height);
    waterPx = new Uint8Array(r.width * r.height);
    let n = 0;
    let wct = 0;
    for (let k = 0; k < mask.length; k++) {
      if (!mask[k]) continue;
      n++;
      if (waterSet.has(rgbAt(r, k))) {
        wct++;
        waterPx[k] = 1;
      }
    }
    out.waterFraction = n ? wct / n : NaN;
  }

  if (layers.dem) {
    const r = layers.dem;
    const { width: w, height: h } = r;
    const mask = insideMask(ring, b, w, h);
    const sameGrid = layers.water && layers.water.width === w && layers.water.height === h;
    const z = new Float64Array(w * h).fill(NaN);
    for (let k = 0; k < w * h; k++) {
      const v = demMap.get(rgbAt(r, k));
      if (v !== undefined) z[k] = v;
    }
    // 3×3 mean filter: removes the 5–50 m colour-bin "stairs" before taking slopes
    const zs = new Float64Array(w * h).fill(NaN);
    for (let j = 0; j < h; j++) {
      for (let i = 0; i < w; i++) {
        let s = 0;
        let c = 0;
        for (let dj = -1; dj <= 1; dj++) {
          for (let di = -1; di <= 1; di++) {
            const ii = i + di;
            const jj = j + dj;
            if (ii < 0 || jj < 0 || ii >= w || jj >= h) continue;
            const v = z[jj * w + ii];
            if (Number.isFinite(v)) {
              s += v;
              c++;
            }
          }
        }
        if (c && Number.isFinite(z[j * w + i])) zs[j * w + i] = s / c;
      }
    }
    const lat0 = ((b.latMin + b.latMax) / 2) * (Math.PI / 180);
    const dx = ((b.lonMax - b.lonMin) / w) * M_PER_DEG * Math.cos(lat0);
    const dy = ((b.latMax - b.latMin) / h) * M_PER_DEG;
    out.resolutionM = dy;
    const elev: number[] = [];
    const slopes: number[] = [];
    let inside = 0;
    let noElev = 0;
    for (let j = 0; j < h; j++) {
      for (let i = 0; i < w; i++) {
        const k = j * w + i;
        if (!mask[k]) continue;
        inside++;
        if (!Number.isFinite(z[k])) {
          noElev++;
          continue;
        }
        if (sameGrid && waterPx && waterPx[k]) continue;
        elev.push(z[k]);
        const l = zs[j * w + Math.max(0, i - 1)];
        const rr = zs[j * w + Math.min(w - 1, i + 1)];
        const u = zs[Math.max(0, j - 1) * w + i];
        const d = zs[Math.min(h - 1, j + 1) * w + i];
        if ([l, rr, u, d].every(Number.isFinite)) {
          const gx = (rr - l) / ((Math.min(w - 1, i + 1) - Math.max(0, i - 1)) * dx);
          const gy = (d - u) / ((Math.min(h - 1, j + 1) - Math.max(0, j - 1)) * dy);
          slopes.push(100 * Math.hypot(gx, gy));
        }
      }
    }
    // ASTER GDEM has no data over the sea: use it as a fallback water signal
    if (!layers.water && inside && noElev / inside >= 0.5) {
      out.waterFraction = noElev / inside;
      out.waterEstimated = true;
    }
    if (elev.length) {
      const se = elev.sort((a, c) => a - c);
      out.elevMean = se.reduce((a, c) => a + c, 0) / se.length;
      out.elevP90 = quantile(se, 0.9);
      out.elevMax = se[se.length - 1];
    }
    if (slopes.length) {
      const ss = slopes.sort((a, c) => a - c);
      out.slopeMedian = quantile(ss, 0.5);
      out.gentleFraction = ss.filter((s) => s <= GENTLE_SLOPE).length / ss.length;
    }
  }

  if (layers.landslide) {
    const r = layers.landslide;
    const mask = insideMask(ring, b, r.width, r.height);
    let n = 0;
    let hi = 0;
    for (let k = 0; k < mask.length; k++) {
      if (!mask[k]) continue;
      const c = slideMap.get(rgbAt(r, k));
      if (c === undefined) continue; // no data (e.g. water)
      n++;
      if (c >= HIGH_CLASS) hi++;
    }
    out.landslideHigh = n ? hi / n : 0;
  }
  return out;
}

/** Download a WMS PNG and decode its exact RGBA pixels (no colour management). */
async function fetchRaster(url: string, signal?: AbortSignal): Promise<Raster> {
  const res = await withRetry(
    async () => {
      const r = await fetch(url, { signal });
      if (!r.ok) throw new HttpError(r.status, '', `GIBS ${r.status}`);
      return r;
    },
    { retries: 3, baseDelayMs: 600, signal },
  );
  const bmp = await createImageBitmap(await res.blob(), { colorSpaceConversion: 'none', premultiplyAlpha: 'none' });
  const canvas = new OffscreenCanvas(bmp.width, bmp.height);
  const ctx = canvas.getContext('2d', { colorSpace: 'srgb' })!;
  ctx.drawImage(bmp, 0, 0);
  const img = ctx.getImageData(0, 0, bmp.width, bmp.height);
  return { data: img.data, width: img.width, height: img.height };
}

export const TERRAIN_LAYERS = {
  water: 'MODIS_Water_Mask',
  dem: 'ASTER_GDEM_Color_Index',
  landslide: 'NDH_Landslide_Hazard_Distribution_2000',
} as const;

/** Fetch and analyse all terrain layers for a polygon. Layers that fail are reported as unavailable. */
export async function fetchTerrain(ring: Ring, b: BBox4, signal?: AbortSignal): Promise<TerrainStats> {
  const { width, height } = rasterSize(b);
  const get = (layer: string, w = width, h = height) => fetchRaster(wmsUrl(layer, b, w, h), signal).catch(() => null);
  const [water, dem, landslide] = await Promise.all([get(TERRAIN_LAYERS.water), get(TERRAIN_LAYERS.dem), get(TERRAIN_LAYERS.landslide)]);
  return analyzeTerrain(ring, b, { water, dem, landslide });
}
